import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the group for this node
  const group = new THREE.Group();

  // Load the texture
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Create plane geometry — atlas region 512×320 → aspect 1.6
  // Sized to match the aspect ratio in scene units
  const width = 1.6;
  const height = 1.0;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Prepare material with texture node
  let material = null;
  const meshPromise = texturePromise.then((texture) => {
    // Set texture properties
    texture.flipY = false;
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;

    // Compute UV scale and offset for atlas region
    // Atlas sheet dimensions assumed 2048×2048 (standard)
    // Region: x=0, y=0, w=512, h=320
    const atlasWidth = 2048;
    const atlasHeight = 2048;
    const regionX = 0;
    const regionY = 0;
    const regionW = 512;
    const regionH = 320;

    const uvScale = new THREE.Vector2(
      regionW / atlasWidth,
      regionH / atlasHeight
    );
    const uvOffset = new THREE.Vector2(
      regionX / atlasWidth,
      regionY / atlasHeight
    );

    // Create material with TSL nodes
    const uvNode = uv().mul(uniform(uvScale)).add(uniform(uvOffset));
    material = new MeshBasicNodeMaterial({
      colorNode: uvNode.uv(texture),
      side: THREE.DoubleSide,
      transparent: true,
    });

    // Create mesh and add to group
    const mesh = new THREE.Mesh(geometry, material);
    group.add(mesh);

    return mesh;
  });

  // Create text label
  const textPromise = Promise.resolve().then(() => {
    const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    const headline = textContent.find((item) => item.role === 'headline') || {
      text: 'Features 3',
      role: 'headline',
      typography: { fontSize: 39 },
    };

    const textObj = ctx.fontAtlas.createText(headline.text, {
      fontSize: headline.typography?.fontSize || 39,
      color: config.intent?.visualSpec?.colors?.ink || '#16161d',
      align: 'center',
    });

    // Position text above/below the sprite
    textObj.position.z = 0.05;
    textObj.position.y = -height / 2 - 0.3;
    group.add(textObj);

    return textObj;
  });

  // Billboarding helper — make plane face camera
  const updateBillboard = (camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  // Attach cleanup
  group.userData.cleanup = () => {
    if (material) material.dispose();
    geometry.dispose();

    // Clean up timelines (none in this spec)
  };

  group.userData.handlers = {
    updateBillboard,
  };

  return group;
}
